import {managementDashboard,submissionsDashboard,filterBar} from './management.mjs';
import {hotels,roles,courses,seed,canHotel,visiblePeople,visibleRecords,metrics,parseCSV,validateImport,csvCell,recoveryDestination,upgradeDemo,managementPeople,managementRecords,managementMetrics,departmentMetrics,visibleSubmissions,submissionActions,transitionSubmission} from './core.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',hotel:'M5 21V3h14v18 M3 21h18 M9 7h1 M14 7h1 M9 11h1 M14 11h1 M10 21v-6h4v6',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.9 M16 3.1a4 4 0 0 1 0 7.8',book:'M3 3h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v16h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3z M12 5v16',calendar:'M3 5h18v16H3z M16 3v4 M8 3v4 M3 11h18 M8 15h2 M14 15h2',upload:'M12 16V3 M7 8l5-5 5 5 M3 16v5h18v-5',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',chart:'M3 3v18h18 M7 16v-4 M12 16V7 M17 16v-7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M19 5l-2 2 M7 17l-2 2',arrow:'M5 12h14 M14 7l5 5-5 5',check:'M5 12l4 4L19 6',logout:'M9 3H3v18h6 M9 12h12 M16 7l5 5-5 5'};
const ico=(n,size=19)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.grid}"/></svg>`;
const key='adnh-learning-demo-v2';let db;try{db=JSON.parse(localStorage.getItem(key));db=upgradeDemo(db)||seed();}catch{db=seed();}let account=null,page='overview',scope='all',loginHotel='SH',loginTab='signin',importKind='people',importResult=null,query='',reportPeriod='2026-11',departmentFilter='all',learningStatus='all',compactDashboard=false;
const hotel=id=>hotels.find(h=>h.id===id),user=()=>db.accounts.find(a=>a.id===account),allowedHotels=()=>hotels.filter(h=>canHotel(user(),h.id));
function save(){try{localStorage.setItem(key,JSON.stringify(db));}catch{toast('Browser storage is full or unavailable. Changes last for this open page only.');}}
function audit(action,target,detail='',department=null){db.audit.unshift({id:crypto.randomUUID(),actor:user()?.name||'Demo applicant',action,target,detail,department:department||user()?.department||null,time:new Date().toISOString()});save();}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function modal(title,body){$('#modal-body').innerHTML=`<div class="modal-title"><h2>${esc(title)}</h2><button data-action="close" aria-label="Close dialog">×</button></div>${body}`;$('#modal').showModal();}
function close(){if($('#modal').open)$('#modal').close();}
const badge=s=>`<span class="tag ${s==='Completed'||s==='Active'?'green':s==='Overdue'||s==='Suspended'?'red':s==='Planned'?'blue':''}">${esc(s)}</span>`;
const brand=`<div class="brand"><div class="brand-symbol">A</div><div><div class="brand-name">ADNH</div><small>ABU DHABI NATIONAL HOTELS</small></div></div>`;
const date=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
function login(){account=null;const h=hotel(loginHotel);$('#app').innerHTML=`<div class="login"><section class="login-visual"><div class="login-bg" style="background-image:url('assets/${h.image}')"></div>${brand}<div class="login-copy"><span class="eyebrow">PEOPLE DEVELOPMENT · FOUR HOTEL CLUSTER</span><h1>Extraordinary hospitality.<br>Inspired by our people.</h1><p>A shared place to learn, grow and bring our best to every guest, every day.</p><div class="login-hotel"><div class="eyebrow" style="color:#d7c2ac">YOUR PROPERTY</div><h3 style="margin:10px 0 0">${esc(h.name)}</h3></div></div><span class="subtle" style="color:#e0d5cb">Four distinctive hotels. One learning community.</span></section><section class="login-side"><div class="login-inner"><span class="eyebrow">WELCOME TO YOUR LEARNING COMMUNITY</span><h1>Your next chapter starts here.</h1><p>Learning, opportunity and progress, brought together.</p><label for="login-hotel">Choose your hotel</label><select id="login-hotel">${hotels.map(x=>`<option value="${x.id}" ${x.id===loginHotel?'selected':''}>${esc(x.name)}</option>`).join('')}</select><div class="tabs"><button data-action="login-tab" data-value="signin" class="${loginTab==='signin'?'active':''}">Sign in</button><button data-action="login-tab" data-value="signup" class="${loginTab==='signup'?'active':''}">Team member sign-up</button></div>${loginTab==='signin'?`<div class="notice">Interactive concept · Sample records only.<br>Use sample credentials only. Live authentication is not connected.</div><form id="member-login"><label for="member-id">Employee ID</label><input id="member-id" name="employee" required placeholder="${h.id}-003" autocomplete="off"><label for="member-password">Password</label><input id="member-password" name="password" type="password" required autocomplete="off" placeholder="Demo password"><div class="flex between" style="margin:10px 0"><small>Sample: ${h.id}-003 · Demo@2026</small><button class="btn text" type="button" data-action="forgot-password">Forgot password?</button></div><button class="btn primary" style="width:100%" type="submit">Sign in to my learning ${ico('arrow',15)}</button></form><details class="demo-roles"><summary>Preview management and trainer views</summary><div class="login-options">${Object.entries(roles).map(([r,label])=>`<button class="login-option" data-action="enter" data-role="${r}">${ico(r==='admin'?'shield':r==='member'?'book':r==='trainer'?'people':r==='hotel'?'hotel':'grid',17)}<span>${label}</span></button>`).join('')}</div><p class="subtle">Hotel and trainer views open for your selected property. Cluster leadership sees its assigned hotels.</p></details>`:`<form id="signup"><p style="font-size:11px">Match your hotel and employee ID to the roster, then request access. Sample IDs for this hotel: ${h.id}-001 to ${h.id}-006.</p><label for="signup-id">Sample employee ID</label><input id="signup-id" name="employee" placeholder="${h.id}-004" required maxlength="40"><label for="signup-email">Recovery email address</label><input id="signup-email" name="email" type="email" placeholder="colleague@example.invalid" required><small>Use an @example.invalid address for this demo.</small><div class="grid2"><div><label for="signup-password">Create password</label><input id="signup-password" name="password" type="password" required autocomplete="off" placeholder="Demo@2026"></div><div><label for="signup-confirm">Confirm password</label><input id="signup-confirm" name="confirm" type="password" required autocomplete="off" placeholder="Demo@2026"></div></div><small>For this prototype, enter Demo@2026 in both fields. Real passwords are not stored.</small><label class="check-row"><input type="checkbox" required> I am using a fictional identity to test the sign-up journey.</label><button class="btn primary" style="width:100%;margin-top:10px" type="submit">Request demo access ${ico('arrow',16)}</button><p class="subtle" style="margin-top:13px">Only the published sample password is accepted. Approval appears in Access & accounts in this browser. No email is sent.</p></form>`}<div class="login-bottom">DESIGNED FOR THE ADNH FOUR HOTEL CLUSTER<br>Prototype by Anhad Tiwari · No paid services connected<br><a href="image-sources.html" target="_blank" rel="noopener">Property photography: hotel galleries</a> · Concept only, not an official employee portal</div></div></section></div>`;}
function enter(role){const id=['hotel','gm','manager','hod','trainer','member'].includes(role)?role+(loginHotel==='SH'?'':'-'+loginHotel):role;const a=db.accounts.find(x=>x.id===id);if(!a?.active)return toast('This demo account is suspended. Use the administrator view to restore it.'); account=id;scope=['admin','cluster'].includes(role)?'all':a.hotels[0]||'all';page=role==='member'?'learning':'overview';query='';departmentFilter=['hod','trainer'].includes(role)?a.department:'all';learningStatus='all';render();}
const navItems=[['overview','grid','Management dashboard'],['properties','hotel','Our hotels'],['people','people','Team members'],['trainers','people','Trainer network'],['sessions','calendar','Learning calendar'],['learning','book','Learning records'],['submissions','chart','Monthly submissions'],['imports','upload','Data centre'],['access','shield','Access & accounts'],['activity','clock','Activity log'],['settings','settings','Design & blueprint']];
function navAllowed(p){const r=user().role;if(r==='member')return ['learning','sessions'].includes(p);if(['trainer','hod'].includes(r))return ['overview','people','sessions','learning','trainers','submissions','activity'].includes(p);if(p==='access'||p==='settings')return r==='admin';if(p==='imports')return ['admin','cluster','hotel'].includes(r);return true;}
function render(){if(!user())return login();if(!user().active)return login();if(!navAllowed(page))page=user().role==='member'?'learning':'overview';if(scope!=='all'&&!canHotel(user(),scope))scope='all';const u=user();$('#app').innerHTML=`<aside class="sidebar">${brand}<div class="workspace-label">PEOPLE DEVELOPMENT</div><nav class="nav">${navItems.filter(x=>navAllowed(x[0])).map(([id,icon,label])=>`<button data-action="nav" data-page="${id}" class="${page===id?'active':''}">${ico(icon)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="flex"><div class="avatar">${u.role==='admin'?'AD':u.role==='cluster'?'CL':hotel(u.hotels[0])?.id||'TM'}</div><div style="font-size:10px">${esc(roles[u.role])}<small>${u.role==='admin'?'All four properties':u.hotels.length+' assigned '+(u.hotels.length===1?'property':'properties')}</small></div></div><button class="btn text" style="color:#c4b4bd;margin:16px 0 0" data-action="logout">${ico('logout',16)} Switch demo role</button></div></aside><div class="shell"><header class="topbar"><button class="mobile-nav" data-action="menu" aria-label="Open menu">☰</button><div class="topbar-title">ADNH <span style="padding:0 9px;color:#c1b4ac">/</span><b>${esc(navItems.find(x=>x[0]===page)?.[2])}</b></div><div class="flex"><select id="scope" aria-label="Property scope">${['admin','cluster'].includes(u.role)?'<option value="all">All assigned properties</option>':''}${allowedHotels().map(h=>`<option value="${h.id}" ${scope===h.id?'selected':''}>${esc(h.short)}</option>`).join('')}${!allowedHotels().length?'<option value="all">No property access</option>':''}</select><span class="tag">SAMPLE DATA</span><div class="avatar" style="width:31px;height:31px">${u.role.slice(0,2).toUpperCase()}</div></div></header><main class="content">${views[page]()}<footer class="footer"><span>ADNH · People Development<br>Concept by Anhad Tiwari</span><span>Local demonstration only · No live employee data<br><a href="image-sources.html" target="_blank" rel="noopener">Hotel imagery © Marriott / Radisson</a></span></footer></main></div>`;if(page==='people'&&query){$('#people-search').value=query;filterPeople();}}
function heading(title,sub,action=''){return `<div class="page-heading"><div><span class="eyebrow">${scope==='all'?'CLUSTER WORKSPACE':esc(hotel(scope)?.short||'YOUR WORKSPACE')}</span><h1 style="margin-top:9px">${title}</h1><p>${sub}</p></div>${action}</div>`;}
function statCards(){const m=user().role==='member'?metrics(db,user(),scope):managementMetrics(db,user(),scope,departmentFilter,reportPeriod);return `<div class="grid4 stats">${[['people','Team members',m.people,'Active sample colleagues'],['clock','Learning hours',m.hours.toFixed(1),'Verified sample completions'],['chart','Completion rate',m.completion==null?'No records':Math.round(m.completion)+'%','Completed / assigned learning'],['shield','Needs attention',m.overdue,'Overdue learning assignments']].map(([i,l,n,s])=>`<div class="card stat"><div class="stat-top">${l}${ico(i)}</div><strong>${n}</strong><small>${s}</small></div>`).join('')}</div>`;}
function hotelCards(){return `<div class="grid4">${allowedHotels().filter(h=>scope==='all'||h.id===scope).map(h=>{const m=metrics(db,user(),h.id);return `<button class="hotel-card" data-action="hotel" data-id="${h.id}"><div class="hotel-photo"><img src="assets/${h.image}" alt="${esc(h.name)}" loading="lazy"><span>${h.brand}</span></div><div class="hotel-body"><h3>${h.short}</h3><p>${h.place}</p><div class="flex between"><span>${m.people} team members</span><b>${m.completion}%</b></div><div class="progress"><i style="width:${m.completion}%"></i></div><div class="flex between" style="margin:12px 0 0;color:#8c7d76"><span>${m.trainers} trainers</span>${ico('arrow',15)}</div></div></button>`}).join('')||'<div class="empty">No hotels assigned. A system administrator can grant property access.</div>'}</div>`;}
function visibleSessions(){return db.sessions.filter(s=>canHotel(user(),s.hotel)&&(scope==='all'||s.hotel===scope)&&(!['trainer','hod'].includes(user().role)||s.department===user().department));}
function managementContext(){return {db,user:user(),scope,department:departmentFilter,period:reportPeriod,compact:compactDashboard,esc,ico,badge};}
function overview(){return managementDashboard(managementContext());}
function filteredPeople(){return managementPeople(db,user(),scope,departmentFilter);}
function filteredLearning(){const rs=user().role==='member'?visibleRecords(db,user(),scope):managementRecords(db,user(),scope,departmentFilter,reportPeriod);return user().role==='member'||learningStatus==='all'?rs:rs.filter(r=>r.status===learningStatus);}
function properties(){return heading('Four hotels. One community.','A clear view of each property, with its own people and priorities.')+hotelCards()+`<div class="notice" style="margin-top:24px">Selecting a hotel applies the same property scope to team members, learning records, the calendar and exports.</div>`;}
function people(){return heading('People at the centre.','One colleague profile. One hotel identity. A clear learning history.',`<button class="btn" data-action="export">Export records</button>`)+`<div class="toolbar"><input id="people-search" aria-label="Search team members" placeholder="Search name, employee ID or department…"><span class="tag">${filteredPeople().length} VISIBLE COLLEAGUES</span></div><div class="card no-padding table-wrap"><table><thead><tr><th>Team member</th><th>Property</th><th>Department</th><th>Learning</th><th>Hours</th><th></th></tr></thead><tbody id="people-body">${peopleRows()}</tbody></table></div>`;}
function peopleRows(){return filteredPeople().filter(p=>[p.name,p.id,p.department].join(' ').toLowerCase().includes(query.toLowerCase())).map(p=>{const rs=db.records.filter(r=>r.employee===p.id&&r.hotel===p.hotel),n=rs.filter(r=>r.status==='Completed').length;return `<tr><td><b>${esc(p.name)}</b><small>${esc(p.id)} · ${p.active?'Active':'Inactive'}</small></td><td>${hotel(p.hotel).short}</td><td>${esc(p.department)}<small>${esc(p.title)}</small></td><td>${n} / ${rs.length} complete</td><td>${rs.filter(r=>r.status==='Completed').reduce((a,r)=>a+r.minutes/60,0).toFixed(1)}</td><td><button class="btn small" data-action="profile" data-id="${p.id}" data-hotel="${p.hotel}">View record</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No colleagues match your search or access.</td></tr>';}
function filterPeople(){$('#people-body').innerHTML=peopleRows();}
function trainers(){const ps=filteredPeople().filter(p=>p.trainer);return heading('A stronger trainer network.','Clear ownership, visible delivery and practical support for every department.')+`<div class="trainer-grid">${ps.map(p=>{const ses=db.sessions.filter(s=>s.trainer===p.id&&s.hotel===p.hotel);return `<div class="card trainer-card"><div class="flex between"><div class="avatar">${p.hotel}</div><span class="tag green">DEMO TRAINER</span></div><h3>${esc(p.name)}</h3><p style="font-size:11px">${esc(p.department)}<br>${hotel(p.hotel).short}</p><div class="flex between"><small>Upcoming sessions</small><b>${ses.length}</b></div><div style="border-top:1px solid #eee4dc;margin:16px 0"></div><div class="flex between"><small>Feedback evidence</small><span class="tag">Not uploaded</span></div><button class="btn" style="width:100%;margin-top:20px" data-action="trainer" data-id="${p.id}" data-hotel="${p.hotel}">View delivery plan ${ico('arrow',14)}</button></div>`}).join('')||'<div class="empty">No trainers in this scope.</div>'}</div>`;}
function sessions(){return heading('Learning that fits the operation.','Plan delivery, confirm nominations and keep completion evidence separate.',['admin','cluster','hotel','hod','trainer'].includes(user().role)?'<button class="btn primary" data-action="new-session">+ Plan a session</button>':'')+`<div class="card no-padding table-wrap"><table><thead><tr><th>Date & time</th><th>Learning session</th><th>Property / trainer</th><th>Duration</th><th>Places</th><th></th></tr></thead><tbody>${visibleSessions().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(s=>`<tr><td><b>${date(s.date)}</b><small>${s.time} UAE</small></td><td><b>${esc(s.name)}</b><small>${esc(s.department)} · ${s.status}</small></td><td>${hotel(s.hotel).short}<small>${esc(db.people.find(p=>p.id===s.trainer&&p.hotel===s.hotel)?.name||s.trainer)}</small></td><td>${s.minutes} min</td><td>${db.nominations.filter(n=>n.session===s.id).length} / ${s.capacity}</td><td><button class="btn small" data-action="session" data-id="${s.id}">Open session</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No sessions in your current scope.</td></tr>'}</tbody></table></div><div class="notice" style="margin-top:20px">A nomination reserves a place. It does not record attendance or add training hours. The live attendance and evidence workflow is included in the implementation blueprint.</div>`;}
function learning(){const self=user().role==='member',p=self?visiblePeople(db,user(),scope)[0]:null;return heading(self?'Your learning. Your progress.':'Every learning record, in one place.',self?'See what you have completed and what comes next.':'Onboarding, service and safety learning, linked to each colleague.',`<button class="btn" data-action="export">${self?'Download my records':'Export records'}</button>`)+(p?`<div class="profile-hero"><div class="avatar">${p.hotel}</div><div><h2>${esc(p.name)}</h2><p>${esc(p.department)} · ${hotel(p.hotel).short}<br><small>Employee ${esc(p.id)} · Joined ${date(p.joined)}</small></p></div></div>`:'')+(self?'':filterBar(managementContext())+`<div class="toolbar"><label for="learning-status">Learning status</label><select id="learning-status" style="max-width:230px">${['all','Completed','Assigned','Overdue'].map(v=>`<option value="${v}" ${learningStatus===v?'selected':''}>${v==='all'?'All statuses':v}</option>`).join('')}</select></div>`)+statCards()+recordTable(filteredLearning(),!self);}
function recordTable(rs,showName=true){return `<div class="card no-padding table-wrap"><table><thead><tr>${showName?'<th>Colleague</th>':''}<th>Learning programme</th><th>Status</th><th>Duration</th><th>Evidence / due date</th></tr></thead><tbody>${rs.map(r=>`<tr>${showName?`<td>${esc(db.people.find(p=>p.id===r.employee&&p.hotel===r.hotel)?.name||r.employee)}<small>${esc(r.employee)} · ${r.hotel}</small></td>`:''}<td>${esc(r.course)}</td><td>${badge(r.status)}</td><td>${r.minutes} min<small>${r.status==='Completed'?'Counted in learning hours':'No hours counted'}</small></td><td>${r.status==='Completed'?date(r.date):r.due?date(r.due):'Not set'}<small>${esc(r.evidence||'Completion evidence pending')}</small></td></tr>`).join('')||`<tr><td colspan="5" class="empty">No learning records yet.</td></tr>`}</tbody></table></div>`;}
function imports(){return heading('Good data. Confident decisions.','Prepare the roster and learning history with a checked import journey.')+`<div class="steps"><span class="step">01 · Download template</span><span class="step">02 · Upload sample CSV</span><span class="step">03 · Review validation</span><span class="step">04 · Confirm import</span></div><div class="grid2"><section class="card"><h2>Upload centre</h2><p>Choose the data you want to prepare. Save your Excel sheet as CSV before uploading.</p><label for="import-kind">Data type</label><select id="import-kind"><option value="people" ${importKind==='people'?'selected':''}>Team member roster</option><option value="records" ${importKind==='records'?'selected':''}>Learning completion records</option></select><div class="drop">${ico('upload',30)}<h3>Start with a sample file</h3><p style="font-size:11px">CSV format · Up to 500 rows · Maximum 1 MB</p><input type="file" id="csv-file" accept=".csv,text/csv" aria-label="Upload sample CSV"><label class="check-row" style="justify-content:center"><input id="demo-data-only" type="checkbox"> This file contains fictional test records only.</label></div><button class="btn" data-action="template">Download ${importKind==='people'?'roster':'learning'} template ↓</button><div id="import-preview" style="margin-top:20px"></div></section><section class="card"><h2>Before your data arrives</h2><p>Consistent identifiers protect the integrity of every colleague record.</p><table><thead><tr><th>Hotel code</th><th>Property</th></tr></thead><tbody>${hotels.map(h=>`<tr><td><b>${h.id}</b></td><td>${h.short}</td></tr>`).join('')}</tbody></table><div class="notice" style="margin-top:20px">This free prototype keeps test data in your current browser only. It does not upload to a server or sync between devices. Do not add real colleague details, passwords, certificates or IDs.</div><p class="subtle" style="margin:18px 0 0">The importer adds validated new records only. Existing records are protected from silent replacement. A full roster reconciliation workflow belongs in the secure live implementation.</p></section></div>`;}
function access(){return heading('The right access. For the right people.','Assign hotels, review requests and keep accountability visible.')+`<div class="notice" style="margin-bottom:20px">Demo administration only. Changes affect sample accounts in this browser. Password reset controls record a simulated request; no password or email is generated.</div><section class="card no-padding table-wrap"><table><thead><tr><th>Account</th><th>Role</th><th>Property access</th><th>Status</th><th></th></tr></thead><tbody>${db.accounts.map(a=>`<tr><td><b>${esc(a.name)}</b><small>${esc(a.employee||a.id)}</small></td><td>${roles[a.role]}</td><td>${a.role==='admin'?'All four properties':a.hotels.map(h=>hotel(h)?.short).join('<br>')||'No property access'}</td><td>${badge(a.active?'Active':'Suspended')}</td><td>${a.role==='admin'?'<small>Owner account</small>':`<button class="btn small" data-action="manage" data-id="${a.id}">Manage</button>`}</td></tr>`).join('')}</tbody></table></section><div class="section-title"><h2>Team member sign-up requests</h2><span class="tag">${db.requests.filter(r=>r.status==='Pending').length} TO REVIEW</span></div><section class="card no-padding table-wrap"><table><thead><tr><th>Colleague / match</th><th>Property</th><th>Demo email</th><th>Status</th><th>Review</th></tr></thead><tbody>${db.requests.map(r=>`<tr><td>${esc(r.name)}<small>${esc(r.employee)} · Exact roster match</small></td><td>${hotel(r.hotel).short}</td><td>${esc(r.email)}</td><td>${badge(r.status)}</td><td>${r.status==='Pending'?`<button class="btn small" data-action="approve" data-id="${r.id}">Approve</button> <button class="btn text" data-action="reject" data-id="${r.id}">Decline</button>`:r.status==='Approved'?`<button class="btn small" data-action="preview-account" data-id="${r.account}">Preview member</button>`:'Reviewed'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No sign-up requests yet.<br>Use “Switch demo role”, open Team member sign-up, then return here to review.</td></tr>'}</tbody></table></section>`;}
function activity(){const logs=db.audit.filter(a=>(user().role==='admin'||allowedHotels().some(h=>a.target.startsWith(h.id)))&&(!['trainer','hod'].includes(user().role)||a.department===user().department));return heading('A clear record of every action.','Named ownership, timing and change details for the demo journeys.')+`<section class="card"><div class="timeline">${logs.map(a=>`<div class="timeline-item"><b>${esc(a.action)}</b><p>${esc(a.target)}${a.detail?' · '+esc(a.detail):''}</p><small>${esc(a.actor)} · ${new Date(a.time).toLocaleString('en-GB',{timeZone:'Asia/Dubai'})} UAE</small></div>`).join('')||'<div class="empty">Your activity log is ready.<br>Try a sample import, nomination or access change to see the record here.</div>'}</div></section>`;}
function settings(){return heading('Purposeful by design.','A simpler cluster workspace, informed by the current trainer system.')+`<div class="card"><h2>Choose a visual direction</h2><p>Property photographs and individual hotel identity remain consistent across all options.</p><div class="theme-options">${[['plum','Heritage · Plum & champagne'],['navy','Coastal · Navy & sand'],['olive','Garden · Olive & stone']].map(([v,l])=>`<button class="theme-option ${document.body.dataset.theme===v?'active':''}" data-action="theme" data-value="${v}">${l}</button>`).join('')}</div></div><div class="section-title"><h2>What stays, what becomes simpler</h2></div><div class="card no-padding table-wrap"><table><thead><tr><th>Decision</th><th>Current workflow</th><th>ADNH direction</th></tr></thead><tbody><tr><td>${badge('Retain')}</td><td>Trainers, sessions, attendance, nominations, evaluations</td><td>One learning journey, tied to a hotel and colleague identity.</td></tr><tr><td>${badge('Consolidate')}</td><td>Separate orientation, mandatory training and programme trackers</td><td>One learning record and compliance framework with configurable programmes.</td></tr><tr><td>${badge('Consolidate')}</td><td>Multiple calendars, submission routes and report screens</td><td>One calendar, one data centre and consistent scoped exports.</td></tr><tr><td>${badge('Keep optional')}</td><td>Cross training, leadership learning and quizzes</td><td>Enable when the cluster needs them; keep the core navigation focused.</td></tr><tr><td>${badge('Exclude')}</td><td>Rixos / Ennismore / Aldar-specific programmes and named historical patches</td><td>No brand content, employee data or one-off correction rules copied into ADNH.</td></tr><tr><td>${badge('Exclude')}</td><td>Department meetings and daily huddles; exam booking as a general team member menu; operational briefing PDF parsing</td><td>Track compliance requirements without exposing specialist administration to everyone.</td></tr></tbody></table></div><div class="section-title"><h2>Problems reviewed and upgrade decisions</h2></div><div class="card no-padding table-wrap"><table><thead><tr><th>Issue / evidence</th><th>Upgrade</th><th>Prototype status</th></tr></thead><tbody>${[
['Single-hotel employee IDs and department-based access in current source','Hotel + employee identity; separate personal, trainer, hotel, cluster and admin views.','Demonstrated; server enforcement required'],
['Duplicate IDs, rehires and partial roster imports in the repair history','Validate duplicates and hotel matching; preview before import; preserve history during reconciliation.','Validation demonstrated; reconciliation planned'],
['Duration and reporting discrepancies reported in prior work','Store minutes; count only completed learning; derive cards and exports from the same filtered records.','Demonstrated'],
['Nomination, attendance and certificate stages can be confused','Keep bookings separate; require evidence before completion or certification.','Nomination separation demonstrated; evidence workflow planned'],
['Department transfers previously changed historical attribution','Effective-dated employment and append-only transfer history.','Live schema design required'],
['Certificate upload previously displayed success without a saved file','Only acknowledge verified storage; keep attendance, result, certificate and expiry separate.','Secure evidence storage planned'],
['Incomplete exports and misleading summary values','Scoped exports with counts and explicit coverage; never label a partial export complete.','CSV learning export demonstrated'],
['Cold-start repairs, stuck loaders and stale requests in repair history','Move migrations out of read requests; small summary queries; bounded retries and clear failure states.','Backend implementation requirement'],
['Shared administrative identity limits accountability','Named accounts, approved grants, reset requests and actor logs.','Local simulation; secure auth required'],
['Rixos-specific targets and deadline rules','Property-configurable learning targets, eligibility and due dates; no automatic carry-over.','No unapproved target applied']
].map(([a,b,c])=>`<tr><td>${a}</td><td>${b}</td><td><small>${c}</small></td></tr>`).join('')}</tbody></table></div><section class="card" style="margin-top:22px"><h2>Live-system boundary</h2><p>This is a public, static demonstration on GitHub Pages. The role selector and sample password are not authentication. All sample records are available to the browser, and local checks can be bypassed. The activity log is a demo log, not tamper-proof evidence.</p><p>A live rollout needs server-enforced permissions, verified identity, recovery to the verified email on file only, protected file storage, transactional imports, backups and cross-device testing. No paid backend, subscription, card or external sign-up has been connected.</p><div class="flex between"><small>Review basis: current portal source, repair record and operations guide, 26 November 2026. Historical repaired issues are not asserted to remain live.</small><button class="btn" data-action="reset-demo">Reset sample workspace</button></div></section>`;}
const views={overview,submissions:()=>submissionsDashboard(managementContext()),properties,people,trainers,sessions,learning,imports,access,activity,settings};
function download(name,rows){const blob=new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
function exportRecords(){const rs=filteredLearning();download(`ADNH_${scope}_Learning_Records_DEMO.csv`,[['hotel_id','employee_id','name','department','course','status','duration_minutes','credited_hours','completion_date','due_date','evidence','data_type'],...rs.map(r=>{const p=db.people.find(p=>p.id===r.employee&&p.hotel===r.hotel);return[r.hotel,r.employee,p?.name,p?.department,r.course,r.status,r.minutes,r.status==='Completed'?r.minutes/60:0,r.status==='Completed'?r.date:'',r.due,r.evidence,'SYNTHETIC DEMO'];})]);toast(`Exported ${rs.length} sample learning records in your current scope.`);}
function showProfile(id,h){const p=visiblePeople(db,user(),scope).find(p=>p.id===id&&p.hotel===h);if(!p)return toast('This record is outside your current view.');modal(p.name,`<p>${esc(p.id)} · ${hotel(h).short}<br>${esc(p.department)} · Joined ${date(p.joined)}</p>`+recordTable(db.records.filter(r=>r.employee===p.id&&r.hotel===p.hotel),false));}
function showSession(id){const s=visibleSessions().find(s=>s.id===id);if(!s)return;const noms=db.nominations.filter(n=>n.session===id),ps=visiblePeople(db,user(),s.hotel).filter(p=>p.active&&!noms.some(n=>n.employee===p.id));modal(s.name,`<p>${hotel(s.hotel).name}<br>${date(s.date)} · ${s.time} UAE · ${s.minutes} minutes</p><div class="flex between">${badge(s.status)}<span>${noms.length} / ${s.capacity} places reserved</span></div><h3 style="margin-top:24px">Nominations</h3>${noms.length?`<ul>${noms.filter(n=>user().role!=='member'||n.employee===user().employee).map(n=>`<li>${esc(db.people.find(p=>p.id===n.employee&&p.hotel===s.hotel)?.name||n.employee)}</li>`).join('')||'<li>Other colleagues have reserved places.</li>'}</ul>`:'<p>No nominations yet.</p>'}${['admin','cluster','hotel','hod','trainer','member'].includes(user().role)?`<form id="nominate" data-session="${id}"><label for="nominee">${user().role==='member'?'Reserve your place':'Choose a colleague in your scope'}</label><select name="employee" id="nominee" required>${ps.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.id)}</option>`).join('')}</select><button class="btn primary" style="margin-top:15px" ${!ps.length||noms.length>=s.capacity?'disabled':''}>Confirm demo nomination</button></form>`:''}<div class="notice" style="margin-top:18px">Booking only. No attendance or learning hours will be added.</div>`);}
function manage(id){if(user().role!=='admin')return;const a=db.accounts.find(x=>x.id===id);if(!a||a.role==='admin')return;modal('Manage account',`<p><b>${esc(a.name)}</b><br>${roles[a.role]} · ${a.active?'Active':'Suspended'}</p><form id="grants" data-id="${id}"><label>Assigned properties</label>${hotels.map(h=>`<label class="grant"><input type="checkbox" name="hotels" value="${h.id}" ${a.hotels.includes(h.id)?'checked':''}>${h.short}</label>`).join('')}${['hod','trainer'].includes(a.role)?`<label for="account-department">Assigned department</label><select id="account-department" name="department">${[...new Set(db.people.map(p=>p.department))].sort().map(dep=>`<option value="${esc(dep)}" ${a.department===dep?'selected':''}>${esc(dep)}</option>`).join('')}</select>`:''}<p class="subtle">Team member and trainer records remain tied to their roster identity and department, even if another property is assigned.</p><label for="grant-reason">Reason for access change</label><input id="grant-reason" name="reason" required placeholder="e.g. Temporary cluster support"><div class="modal-actions"><button type="button" class="btn" data-action="suspend" data-id="${id}">${a.active?'Suspend':'Restore'} account</button><button class="btn primary">Save property access</button></div></form><button class="btn text" style="margin-top:15px" data-action="password-reset" data-id="${id}">Simulate password reset request</button>`);}
function newSession(){if(!['admin','cluster','hotel','hod','trainer'].includes(user().role))return;modal('Plan a learning session',`<form id="session-form"><label for="session-name">Session title</label><input id="session-name" name="name" required maxlength="120"><div class="grid2"><div><label for="session-hotel">Property</label><select id="session-hotel" name="hotel">${allowedHotels().filter(h=>scope==='all'||scope===h.id).map(h=>`<option value="${h.id}">${h.short}</option>`).join('')}</select></div><div><label for="session-trainer">Trainer</label><select id="session-trainer" name="trainer"></select></div></div><div class="grid2"><div><label for="session-date">Date</label><input id="session-date" name="date" type="date" required value="2026-11-30"></div><div><label for="session-time">Time (UAE)</label><input id="session-time" name="time" type="time" required value="10:00"></div></div><div class="grid2"><div><label for="session-minutes">Duration in minutes</label><input id="session-minutes" name="minutes" type="number" required min="1" max="1440" value="60"></div><div><label for="session-capacity">Capacity</label><input id="session-capacity" name="capacity" type="number" required min="1" max="500" value="15"></div></div><div class="modal-actions"><button class="btn primary">Save demo session</button></div></form>`);updateTrainerOptions();}
function updateTrainerOptions(){const h=$('#session-hotel')?.value;if(!h)return;$('#session-trainer').innerHTML=visiblePeople(db,user(),h).filter(p=>p.trainer).map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.department)}</option>`).join('');}
async function previewImport(){if(!$('#demo-data-only').checked){$('#csv-file').value='';return toast('Confirm that the file contains fictional test records only, then choose it again.');}const file=$('#csv-file').files[0];if(!file)return;if(file.size>1024*1024){$('#csv-file').value='';return toast('Please use a CSV smaller than 1 MB.');}try{const rows=parseCSV(await file.text());importResult=validateImport(rows,importKind,db,user());const {errors,items}=importResult;$('#import-preview').innerHTML=errors.length?`<div class="error"><b>Import paused. No rows have been saved.</b><ul>${errors.slice(0,12).map(e=>`<li>${esc(e)}</li>`).join('')}</ul>${errors.length>12?`${errors.length-12} more issues. Correct the file and try again.`:''}</div>`:`<div class="success"><b>${items.length} valid rows ready to review.</b><p style="margin-bottom:0">No records will be overwritten.</p></div><div class="table-wrap"><table><thead><tr><th>Hotel</th><th>Employee ID</th><th>${importKind==='people'?'Name':'Programme'}</th></tr></thead><tbody>${items.slice(0,8).map(r=>`<tr><td>${r.hotel_id}</td><td>${esc(r.employee_id)}</td><td>${esc(r.name||r.course)}</td></tr>`).join('')}</tbody></table></div><button class="btn primary" style="margin-top:15px" data-action="commit-import">Import ${items.length} sample rows</button>`;}catch(e){importResult=null;$('#import-preview').innerHTML=`<div class="error">${esc(e.message)}</div>`;}}
function commitImport(){if(!importResult||importResult.errors.length||!['admin','cluster','hotel'].includes(user().role))return;const n=importResult.items.length;for(const r of importResult.items){if(importKind==='people')db.people.push({id:r.employee_id,hotel:r.hotel_id,name:r.name,department:r.department,title:'Team Member',email:'',joined:r.joining_date,active:true,trainer:false});else db.records.push({id:crypto.randomUUID(),employee:r.employee_id,hotel:r.hotel_id,course:r.course,status:r.status,minutes:Number(r.duration_minutes),date:r.completion_date,due:'',evidence:r.status==='Completed'?'Imported sample completion':''});}audit('Imported sample '+importKind,scope==='all'?'Cluster':scope,`${n} new rows; no existing records replaced`);importResult=null;render();toast(`${n} sample rows imported into this browser.`);}
function template(){const h=scope==='all'?allowedHotels()[0]?.id:scope;if(!h)return toast('No property access.');download(`ADNH_${importKind}_Template.csv`,importKind==='people'?[['hotel_id','employee_id','name','department','joining_date'],[h,`${h}-DEMO101`,'Demo New Colleague','Front Office','2026-11-26']]:[['hotel_id','employee_id','course','status','duration_minutes','completion_date'],[h,`${h}-001`,'Demo product knowledge','Completed','60','2026-11-26']]);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;switch(a){case'enter':enter(b.dataset.role);break;case'forgot-password':modal('Recover your account',`<p>Enter your employee ID. Recovery is sent only to the registered email already saved on your account.</p><form id="recovery"><p><b>${esc(hotel(loginHotel).name)}</b></p><label for="recovery-id">Employee ID</label><input id="recovery-id" name="employee" required placeholder="${loginHotel}-003"><div class="notice" style="margin-top:18px">Only the email on file can receive a reset link. This demo records the request without sending email. If you cannot access that email, contact your hotel People & Culture team.</div><div class="modal-actions"><button class="btn primary">Preview recovery request</button></div></form>`);break;case'login-tab':loginTab=b.dataset.value;login();break;case'logout':scope='all';login();break;case'nav':page=b.dataset.page;query='';render();window.scrollTo(0,0);break;case'hotel':scope=id;page='overview';render();window.scrollTo(0,0);break;case'menu':$('.sidebar').classList.toggle('open');break;case'close':close();break;case'export':exportRecords();break;case'toggle-dashboard':compactDashboard=!compactDashboard;render();break;case'management-export':exportManagement();break;case'department-drill':if(canHotel(user(),b.dataset.hotel)){scope=b.dataset.hotel;departmentFilter=b.dataset.department;page='overview';render();window.scrollTo(0,0);}break;case'management-records':learningStatus=b.dataset.filter||'all';page='learning';render();break;case'review-submission':reviewSubmission(id,b.dataset.value);break;case'profile':showProfile(id,b.dataset.hotel);break;case'session':showSession(id);break;case'new-session':newSession();break;case'trainer':{const p=visiblePeople(db,user(),scope).find(x=>x.id===id&&x.hotel===b.dataset.hotel);if(!p)return;modal(p.name,`<p>${esc(p.department)} · ${hotel(p.hotel).short}</p>${db.sessions.filter(s=>s.trainer===p.id&&s.hotel===p.hotel).map(s=>`<div class="session-row"><div class="date-box">NOV<b>${s.date.slice(-2)}</b></div><div><h3>${esc(s.name)}</h3><small>${s.time} · ${s.minutes} min · ${s.status}</small></div></div>`).join('')||'<p>No upcoming delivery yet.</p>'}<div class="notice" style="margin-top:20px">Trainer feedback will appear when evaluations and attendance evidence are connected. No rating is inferred from planned sessions.</div>`);break;}case'manage':manage(id);break;case'suspend':{if(user().role!=='admin')return;const x=db.accounts.find(a=>a.id===id);if(!x||x.role==='admin')return;x.active=!x.active;audit(x.active?'Restored demo account':'Suspended demo account',id);close();render();toast('Demo account status updated.');break;}case'password-reset':if(user().role==='admin'){audit('Simulated password reset',id,'No email sent and no password changed');close();render();toast('Reset request simulated. No email sent or password changed.');}break;case'approve':case'reject':{if(user().role!=='admin')return;const r=db.requests.find(x=>x.id===id);if(!r||r.status!=='Pending')return;r.status=a==='approve'?'Approved':'Declined';if(a==='approve'){const p=db.people.find(p=>p.id===r.employee&&p.hotel===r.hotel);if(!p?.active)return toast('Roster record is no longer active.');r.account=crypto.randomUUID();db.accounts.push({id:r.account,name:r.name,email:r.email,role:'member',hotels:[r.hotel],employee:r.employee,employeeHotel:r.hotel,department:p.department,active:true});}audit('Sign-up '+r.status.toLowerCase(),`${r.hotel}/${r.employee}`,'Exact roster identity reviewed');render();toast(`Demo request ${r.status.toLowerCase()}.`);break;}case'preview-account':{const x=db.accounts.find(a=>a.id===id);if(user().role!=='admin'||!x?.active)return;account=id;scope=x.hotels[0]||'all';page='learning';render();break;}case'template':template();break;case'commit-import':commitImport();break;case'theme':document.body.dataset.theme=b.dataset.value;localStorage.setItem('adnh-theme',b.dataset.value);render();break;case'reset-demo':modal('Reset sample workspace?',`<p>This clears locally imported sample records, requests and access changes, then restores the original demonstration. It does not affect any live system.</p><div class="modal-actions"><button class="btn" data-action="close">Cancel</button><button class="btn primary" data-action="confirm-reset">Reset sample data</button></div>`);break;case'confirm-reset':if(user().role==='admin'){db=seed();save();close();scope='all';departmentFilter='all';render();toast('Sample workspace restored.');}break;}});
document.addEventListener('change',e=>{switch(e.target.id){case'login-hotel':loginHotel=e.target.value;login();break;case'scope':scope=e.target.value;query='';departmentFilter=['hod','trainer'].includes(user().role)?user().department:'all';importResult=null;render();break;case'management-period':reportPeriod=e.target.value;render();break;case'management-department':departmentFilter=e.target.value;render();break;case'learning-status':learningStatus=e.target.value;render();break;case'import-kind':importKind=e.target.value;importResult=null;render();break;case'csv-file':previewImport();break;case'session-hotel':updateTrainerOptions();break;}});
document.addEventListener('input',e=>{if(e.target.id==='people-search'){query=e.target.value;filterPeople();}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='member-login'){const employee=d.get('employee').trim().toUpperCase(),a=db.accounts.find(a=>a.employee===employee&&a.employeeHotel===loginHotel);if(d.get('password')!=='Demo@2026')return toast('This prototype accepts only Demo@2026. Do not use a real password.');if(!a||!a.active||!a.hotels.includes(loginHotel))return toast('No approved active demo account matches this hotel and employee ID.');account=a.id;scope=loginHotel;page=a.role==='member'?'learning':'overview';render();toast('Signed in to your sample learning record.');}if(f.id==='recovery'){const employee=d.get('employee').trim().toUpperCase();const destination=recoveryDestination(db,loginHotel,employee);if(destination){db.audit.unshift({id:crypto.randomUUID(),actor:'Demo recovery journey',action:'Requested demo password recovery',target:loginHotel+'/'+employee,detail:'Destination resolved from the account email on file; no email sent and no credential changed',time:new Date().toISOString()});save();}close();toast('Demo recovery preview complete. An eligible account would receive a reset link only at its verified email on file. No email was sent.');}if(f.id==='signup'){if(d.get('password')!=='Demo@2026'||d.get('confirm')!=='Demo@2026')return toast('Use Demo@2026 in both password fields. Do not enter a real password.');if(!d.get('email').trim().endsWith('@example.invalid'))return toast('Use a fictional @example.invalid recovery email in this prototype.');const id=d.get('employee').trim().toUpperCase(),email=d.get('email').trim(),p=db.people.find(p=>p.id===id&&p.hotel===loginHotel&&p.active);if(!p)return toast('No active sample colleague matches this hotel and employee ID.');if(db.accounts.some(a=>a.employee===id&&a.employeeHotel===loginHotel)||db.requests.some(r=>r.employee===id&&r.hotel===loginHotel&&r.status!=='Declined'))return toast('This colleague already has a demo account or pending request.');db.requests.unshift({id:crypto.randomUUID(),employee:id,hotel:loginHotel,name:p.name,email,status:'Pending'});audit('Submitted demo sign-up',`${loginHotel}/${id}`);loginTab='signin';login();toast('Demo request submitted. Open System administrator → Access & accounts to review.');}
if(f.id==='grants'){if(user().role!=='admin')return;const a=db.accounts.find(a=>a.id===f.dataset.id);if(!a||a.role==='admin')return;const before=[...a.hotels],oldDepartment=a.department;if(['hod','trainer'].includes(a.role)&&db.people.some(p=>p.department===d.get('department')))a.department=d.get('department');a.hotels=d.getAll('hotels').filter(h=>hotels.some(x=>x.id===h));audit('Changed property access',a.id,`${before.join(', ')||'None'} → ${a.hotels.join(', ')||'None'}. ${d.get('reason')}${['hod','trainer'].includes(a.role)?'; Department: '+oldDepartment+' → '+a.department:''}`);close();render();toast('Property access updated in this demo.');}
if(f.id==='nominate'){const s=visibleSessions().find(s=>s.id===f.dataset.session),id=d.get('employee');if(!s||!['admin','cluster','hotel','hod','trainer','member'].includes(user().role))return;if(!visiblePeople(db,user(),s.hotel).some(p=>p.id===id))return toast('Colleague is outside your access.');if(db.nominations.some(n=>n.session===s.id&&n.employee===id))return toast('Already nominated.');if(db.nominations.filter(n=>n.session===s.id).length>=s.capacity)return toast('This session is full.');db.nominations.push({session:s.id,employee:id,hotel:s.hotel});audit('Added demo nomination',`${s.hotel}/${id}`,s.name);close();render();toast('Place reserved. No training hours added.');}
if(f.id==='submission-review'){try{const change=transitionSubmission(db,user(),f.dataset.id,f.dataset.next,d.get('note'));audit('Monthly report '+change.after.toLowerCase(),change.hotel+'/'+change.department,change.month+': '+change.before+' → '+change.after+'. '+d.get('note'),change.department);close();render();toast('Demo report status updated. Learning hours are unchanged.');}catch(err){toast(err.message);}}if(f.id==='session-form'){if(!['admin','cluster','hotel','hod','trainer'].includes(user().role))return;const h=d.get('hotel'),p=visiblePeople(db,user(),h).find(p=>p.id===d.get('trainer')&&p.trainer);if(!canHotel(user(),h)||!p)return toast('Select an authorised property and trainer.');const minutes=Number(d.get('minutes')),capacity=Number(d.get('capacity'));if(minutes<1||minutes>1440||capacity<1||capacity>500)return;db.sessions.push({id:crypto.randomUUID(),hotel:h,name:d.get('name').trim(),date:d.get('date'),time:d.get('time'),minutes,capacity,trainer:p.id,department:p.department,status:'Planned'});audit('Planned demo session',h,d.get('name'));close();render();toast('Session added to the learning calendar.');}});
try{document.body.dataset.theme=localStorage.getItem('adnh-theme')||'plum';}catch{document.body.dataset.theme='plum';}login();

function exportManagement(){const rows=departmentMetrics(db,user(),scope,departmentFilter,reportPeriod);download('ADNH_Management_'+reportPeriod+'_DEMO.csv',[['reporting_period','hotel','department','active_colleagues','total_hours','average_hours','on_job_hours','on_job_average','off_job_hours','online_hours','unclassified_hours','participation_percent','orientation_pending','overdue_learning','headcount_basis','data_type'],...rows.map(r=>[reportPeriod,hotel(r.hotel).name,r.department,r.people,r.hours,r.average,r.modes.on_job,r.people?r.modes.on_job/r.people:'',r.modes.off_job,r.modes.online,r.modes.unclassified,r.participation,r.orientationTotal?r.orientationPending:'No records',r.overdue,'Current active sample roster','SYNTHETIC DEMO'])]);toast('Exported '+rows.length+' department rows for the selected period and scope.');}
function reviewSubmission(id,next){const s=visibleSubmissions(db,user(),scope,departmentFilter,reportPeriod).find(x=>x.id===id);if(!s||!submissionActions(user(),s).includes(next))return toast('This review action is outside your access.');modal(next==='Draft'?'Return for correction':'Review monthly submission',`<p><b>${esc(s.department)}</b><br>${hotel(s.hotel).short} · ${s.month}</p><p>${esc(s.status)} → ${esc(next)}</p><form id="submission-review" data-id="${esc(id)}" data-next="${esc(next)}"><label for="review-note">Review note / reason</label><textarea id="review-note" name="note" required maxlength="500" placeholder="Record what was checked or needs correction."></textarea><div class="notice" style="margin-top:15px">This changes the sample review status only. It does not create attendance or learning hours.</div><div class="modal-actions"><button class="btn" type="button" data-action="close">Cancel</button><button class="btn primary">Confirm demo review</button></div></form>`);}
